import Complex128Array = require( '@stdlib/array/complex128' );
import Complex128 = require( '@stdlib/complex/float64/ctor' );
import zrotg = require( './index' );


// TESTS //

// The function returns a Complex128Array...
{
    const za = new Complex128( 1.0, 1.0 );
    const zb = new Complex128( 2.0, 2.0 );

	zrotg( za, zb ); // $ExpectType Complex128Array
}

// The compiler throws an error if the function is provided an argument which is not a number...
{
    const za = new Complex128( 1.0, 1.0 );
    const zb = new Complex128( 2.0, 2.0 );

	zrotg( true, zb ); // $ExpectError
	zrotg( false, zb ); // $ExpectError
	zrotg( null, zb ); // $ExpectError
	zrotg( undefined, zb ); // $ExpectError
	zrotg( '5', zb ); // $ExpectError
	zrotg( [], zb ); // $ExpectError
	zrotg( {}, zb ); // $ExpectError

	zrotg( za, true ); // $ExpectError
	zrotg( za, false ); // $ExpectError
	zrotg( za, null ); // $ExpectError
	zrotg( za, undefined ); // $ExpectError
	zrotg( za, '5' ); // $ExpectError
	zrotg( za, [] ); // $ExpectError
	zrotg( za, {} ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
    const za = new Complex128( 1.0, 1.0 );
    const zb = new Complex128( 2.0, 2.0 );

	zrotg(); // $ExpectError
	zrotg( za ); // $ExpectError
	zrotg( za, zb, 3.0 ); // $ExpectError
}

// Attached to the main export is an `assign` method which returns a Complex128Array...
{
    const za = new Complex128( 1.0, 1.0 );
    const zb = new Complex128( 2.0, 2.0 );
	const out = new Complex128Array( 4 );

	zrotg.assign( za, zb, out, 1, 0 ); // $ExpectType Complex128Array
}

// The compiler throws an error if the `assign` method is provided a first or second argument which is not a number...
{
    const za = new Complex128( 1.0, 1.0 );
    const zb = new Complex128( 2.0, 2.0 );
	const out = new Complex128Array( 4 );

	zrotg.assign( true, zb, out, 1, 0 ); // $ExpectError
	zrotg.assign( false, zb, out, 1, 0 ); // $ExpectError
	zrotg.assign( null, zb, out, 1, 0 ); // $ExpectError
	zrotg.assign( undefined, zb, out, 1, 0 ); // $ExpectError
	zrotg.assign( '5', zb, out, 1, 0 ); // $ExpectError
	zrotg.assign( [], zb, out, 1, 0 ); // $ExpectError
	zrotg.assign( {}, zb, out, 1, 0 ); // $ExpectError

	zrotg.assign( za, true, out, 1, 0 ); // $ExpectError
	zrotg.assign( za, false, out, 1, 0 ); // $ExpectError
	zrotg.assign( za, null, out, 1, 0 ); // $ExpectError
	zrotg.assign( za, undefined, out, 1, 0 ); // $ExpectError
	zrotg.assign( za, '5', out, 1, 0 ); // $ExpectError
	zrotg.assign( za, [], out, 1, 0 ); // $ExpectError
	zrotg.assign( za, {}, out, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `assign` method is provided a third argument which is not a Complex128Array...
{
    const za = new Complex128( 1.0, 1.0 );
    const zb = new Complex128( 2.0, 2.0 );

	zrotg.assign( za, zb, 1, 1, 0 ); // $ExpectError
	zrotg.assign( za, zb, true, 1, 0 ); // $ExpectError
	zrotg.assign( za, zb, false, 1, 0 ); // $ExpectError
	zrotg.assign( za, zb, null, 1, 0 ); // $ExpectError
	zrotg.assign( za, zb, undefined, 1, 0 ); // $ExpectError
	zrotg.assign( za, zb, '5', 1, 0 ); // $ExpectError
	zrotg.assign( za, zb, [], 1, 0 ); // $ExpectError
	zrotg.assign( za, zb, {}, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `assign` method is provided a fourth argument which is not a number...
{
    const za = new Complex128( 1.0, 1.0 );
    const zb = new Complex128( 2.0, 2.0 );
	const out = new Complex128Array( 4 );

	zrotg.assign( za, zb, out, '5', 0 ); // $ExpectError
	zrotg.assign( za, zb, out, true, 0 ); // $ExpectError
	zrotg.assign( za, zb, out, false, 0 ); // $ExpectError
	zrotg.assign( za, zb, out, null, 0 ); // $ExpectError
	zrotg.assign( za, zb, out, [], 0 ); // $ExpectError
	zrotg.assign( za, zb, out, {}, 0 ); // $ExpectError
	zrotg.assign( za, zb, out, ( x: number ): number => x, 0 ); // $ExpectError
}

// The compiler throws an error if the `assign` method is provided a fifth argument which is not a number...
{
    const za = new Complex128( 1.0, 1.0 );
    const zb = new Complex128( 2.0, 2.0 );
	const out = new Complex128Array( 4 );

	zrotg.assign( za, zb, out, 1, '5' ); // $ExpectError
	zrotg.assign( za, zb, out, 1, true ); // $ExpectError
	zrotg.assign( za, zb, out, 1, false ); // $ExpectError
	zrotg.assign( za, zb, out, 1, null ); // $ExpectError
	zrotg.assign( za, zb, out, 1, [] ); // $ExpectError
	zrotg.assign( za, zb, out, 1, {} ); // $ExpectError
	zrotg.assign( za, zb, out, 1, ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the `assign` method is provided an unsupported number of arguments...
{
    const za = new Complex128( 1.0, 1.0 );
    const zb = new Complex128( 2.0, 2.0 );
	const out = new Complex128Array( 4 );

	zrotg.assign(); // $ExpectError
	zrotg.assign( za ); // $ExpectError
	zrotg.assign( za, zb ); // $ExpectError
	zrotg.assign( za, zb, out ); // $ExpectError
	zrotg.assign( za, zb, out, 1 ); // $ExpectError
	zrotg.assign( za, zb, out, 1, 0, 1 ); // $ExpectError
}
